function fill(i){const a=artworks[i];for(const [id,value] of Object.entries({'#scroll-theme':a.theme,'#scroll-title':a.title,'#scroll-subtitle':a.subtitle,'#scroll-creator':a.creator,'#scroll-description':a.description,'#scroll-reflection':a.reflection,'#scroll-concepts':a.concepts,'#scroll-connection':a.connection}))$(id).textContent=value;}
function showScroll(){scroll.classList.add('show');scroll.setAttribute('aria-hidden','false');$('#close').focus({preventScroll:true});}
function hideScroll(){scroll.classList.remove('show');scroll.setAttribute('aria-hidden','true');}
function open(i){if(phase!=='idle'||selected!==-1)return;selected=i;fill(i);phase='opening';phaseStart=performance.now();veil.classList.add('show');document.querySelector('.instruction').textContent='THE ARTWORK IS REVEALING ITS STORY';}
