$('#close').onclick=close;veil.onclick=close;document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(selected===-1&&['1','2','3'].includes(e.key))open(+e.key-1)});
document.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>open(+b.dataset.i));
function clamp(x,a,b){return Math.max(a,Math.min(b,x))}function ease(x){x=clamp(x,0,1);return x*x*(3-2*x)}function mix(a,b,t){return a+(b-a)*t}
function makeCanvas(i){const c=document.createElement('canvas');c.width=768;c.height=1024;const g=c.getContext('2d');g.fillStyle='#080707';g.fillRect(0,0,768,1024);
// Three original procedural conceptual artworks, not stock or AI imagery. Replace with student work for submission.
if(i===0){const grad=g.createRadialGradient(380,460,10,380,460,450);grad.addColorStop(0,'#493b2b');grad.addColorStop(.65,'#15100b');grad.addColorStop(1,'#020202');g.fillStyle=grad;g.fillRect(0,0,768,1024);g.strokeStyle='#c5a477';g.lineWidth=14;g.beginPath();g.moveTo(225,155);g.lineTo(540,155);g.moveTo(225,875);g.lineTo(540,875);g.stroke();g.lineWidth=8;g.beginPath();g.moveTo(255,165);g.bezierCurveTo(255,330,525,345,390,505);g.bezierCurveTo(255,675,255,725,255,865);g.moveTo(510,165);g.bezierCurveTo(510,330,250,345,390,505);g.bezierCurveTo(510,675,510,725,510,865);g.stroke();g.fillStyle='#dfb66c';g.beginPath();g.moveTo(278,245);g.lineTo(485,245);g.lineTo(390,475);g.closePath();g.fill();g.beginPath();g.moveTo(390,535);g.lineTo(275,830);g.lineTo(505,830);g.closePath();g.fill();for(let j=0;j<90;j++){g.fillStyle=`rgba(238,197,117,${.1+Math.random()*.6})`;g.fillRect(380+(Math.random()-.5)*20,485+Math.random()*45,2,3)}}
if(i===1){const grad=g.createRadialGradient(390,480,0,390,480,550);grad.addColorStop(0,'#26313a');grad.addColorStop(.4,'#0c1319');grad.addColorStop(1,'#020303');g.fillStyle=grad;g.fillRect(0,0,768,1024);for(let j=0;j<140;j++){let x=Math.random()*768,y=Math.random()*1024,r=Math.random()*2;g.fillStyle=`rgba(216,205,174,${Math.random()*.7})`;g.beginPath();g.arc(x,y,r,0,Math.PI*2);g.fill()}for(let j=0;j<9;j++){g.beginPath();g.arc(385,510,90+j*27,0,Math.PI*2);g.strokeStyle=`rgba(193,165,111,${.55-j*.047})`;g.lineWidth=2;g.stroke()}const orb=g.createRadialGradient(350,420,10,385,510,150);orb.addColorStop(0,'#f1d8a5');orb.addColorStop(.25,'#9b875e');orb.addColorStop(.7,'#2d3336');orb.addColorStop(1,'#07090b');g.fillStyle=orb;g.beginPath();g.arc(385,510,145,0,Math.PI*2);g.fill()}
if(i===2){const grad=g.createRadialGradient(380,490,20,380,490,520);grad.addColorStop(0,'#302318');grad.addColorStop(1,'#030303');g.fillStyle=grad;g.fillRect(0,0,768,1024);const nodes=[[210,300],[550,270],[380,490],[200,730],[560,750]];g.strokeStyle='#b79562';g.lineWidth=8;for(const [a,b] of [[0,2],[1,2],[2,3],[2,4],[0,1],[3,4]]){g.beginPath();g.moveTo(...nodes[a]);g.lineTo(...nodes[b]);g.stroke()}nodes.forEach(([x,y],j)=>{const glow=g.createRadialGradient(x,y,4,x,y,80);glow.addColorStop(0,'#ffe3a4');glow.addColorStop(.16,'#b99761');glow.addColorStop(1,'#a8804000');g.fillStyle=glow;g.beginPath();g.arc(x,y,80,0,Math.PI*2);g.fill();g.fillStyle='#f3d5a0';g.beginPath();g.arc(x,y,12,0,Math.PI*2);g.fill()})}
g.strokeStyle='#ae8c5a';g.lineWidth=3;g.strokeRect(27,27,714,970);g.strokeStyle='#7b6040';g.lineWidth=1;g.strokeRect(42,42,684,940);g.fillStyle='#e3d0b0';g.font='24px Georgia';g.textAlign='center';g.fillText('ORIGINAL ARTWORK PLACEHOLDER',384,940);return new T.CanvasTexture(c)}
function box(w,h,d,material,x,y,z,parent){const m=new T.Mesh(new T.BoxGeometry(w,h,d),material);m.position.set(x,y,z);parent.add(m);return m}
function createFrame(i){const group=new T.Group();const frame=new T.Group();group.add(frame);const gold=new T.MeshStandardMaterial({color:0x8c7148,metalness:.83,roughness:.24});const edge=new T.MeshStandardMaterial({color:0x35291b,metalness:.65,roughness:.36});const black=new T.MeshStandardMaterial({color:0x070606,roughness:.48,metalness:.28});const w=2.3,h=3.1;
box(w+.28,h+.28,.19,black,0,0,-.08,frame);for(const [x,y,sx,sy] of [[0,h/2,w+.33,.13],[0,-h/2,w+.33,.13],[-w/2,0,.13,h+.28],[w/2,0,.13,h+.28]])box(sx,sy,.22,gold,x,y,.06,frame);for(const [x,y,sx,sy] of [[0,h/2-.14,w,.035],[0,-h/2+.14,w,.035],[-w/2+.14,0,.035,h],[w/2-.14,0,.035,h]])box(sx,sy,.025,edge,x,y,.18,frame);
const texture=makeCanvas(i);texture.colorSpace=T.SRGBColorSpace;const mat=new T.MeshStandardMaterial({map:texture,roughness:.58,metalness:.03,side:T.DoubleSide});const painting=new T.Mesh(new T.PlaneGeometry(w-.13,h-.13),mat);painting.position.z=.19;frame.add(painting);painting.userData.i=i;targets.push(painting);
if(artworks[i].image){const loader=new T.TextureLoader();loader.load(artworks[i].image,t=>{t.colorSpace=T.SRGBColorSpace;painting.material.map=t;painting.material.needsUpdate=true;texture.dispose()},undefined,()=>console.warn('Original artwork image missing:',artworks[i].image))}
const light=new T.SpotLight(0xffd9a0,65,11,Math.PI/6,.72,1.6);light.position.set(0,3.5,3.6);light.target.position.set(0,0,0);group.add(light,light.target);
const x=(i-1)*4.2;group.position.set(x,-.12,-3.3-Math.abs(i-1)*.9);scene.add(group);return {group,frame,painting,light,origin:group.position.clone(),texture};}
function buildHall(){const black=new T.MeshStandardMaterial({color:0x090909,metalness:.3,roughness:.8,side:T.DoubleSide});const gold=new T.MeshStandardMaterial({color:0x6e5332,metalness:.8,roughness:.28});const floor=new T.Mesh(new T.PlaneGeometry(120,120),new T.MeshStandardMaterial({color:0x050505,roughness:.25,metalness:.35}));floor.rotation.x=-Math.PI/2;floor.position.y=-3.25;scene.add(floor);const ceiling=new T.Mesh(new T.PlaneGeometry(120,120),black);ceiling.rotation.x=Math.PI/2;ceiling.position.y=4.7;scene.add(ceiling);for(const x of [-7.8,7.8]){const wall=new T.Mesh(new T.PlaneGeometry(120,12),black);wall.rotation.y=Math.PI/2;wall.position.set(x,.5,-24);scene.add(wall)}
for(let z=2;z>-64;z-=8){for(const x of [-7.5,7.5]){box(.16,7.9,.2,gold,x,.5,z,scene);box(.45,.12,7.8,gold,x,-3.18,z-3.8,scene)}box(15.2,.16,.22,gold,0,4.45,z,scene);const bulb=new T.PointLight(0xb18b54,5,12);bulb.position.set(0,4.2,z);scene.add(bulb)}const fog=new T.FogExp2(0x020203,.022);scene.fog=fog;}
async function init(){try{T=await import('https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js');scene=new T.Scene();scene.background=new T.Color(0x020203);camera=new T.PerspectiveCamera(47,1,.1,120);camera.position.set(0,.05,10.8);renderer=new T.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.6));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.18;viewport.appendChild(renderer.domElement);scene.add(new T.AmbientLight(0x6e6559,.35));buildHall();frames=artworks.map((a,i)=>createFrame(i));clock=new T.Clock();const resize=()=>{const w=viewport.clientWidth,h=viewport.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.fov=w<720?64:47;camera.updateProjectionMatrix()};resize();new ResizeObserver(resize).observe(viewport);
const ray=new T.Raycaster(),mouse=new T.Vector2();viewport.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,dist:0}});viewport.addEventListener('pointermove',e=>{if(drag){drag.dist+=Math.abs(e.clientX-drag.x)+Math.abs(e.clientY-drag.y);lookGoal=clamp(lookGoal+(e.clientX-drag.x)*.0006,-.22,.22);drag.x=e.clientX;drag.y=e.clientY}else if(!reduced){const r=viewport.getBoundingClientRect();lookGoal=clamp(((e.clientX-r.left)/r.width-.5)*.16,-.15,.15)}});viewport.addEventListener('pointerup',e=>{if(!drag)return;const d=drag.dist;drag=null;if(d>12||phase!=='idle')return;const r=viewport.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(mouse,camera);const hit=ray.intersectObjects(targets)[0];if(hit)open(hit.object.userData.i)});viewport.addEventListener('pointercancel',()=>drag=null);
new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible&&!raf)animate()}).observe(viewport);document.addEventListener('visibilitychange',()=>{visible=!document.hidden;if(visible&&!raf)animate()});animate();}catch(e){console.error('Museum 3D fallback',e);document.querySelector('.shell').classList.add('no-webgl');const f=$('#fallback');f.hidden=false;artworks.forEach((a,i)=>{const b=document.createElement('button');b.textContent=a.title;b.onclick=()=>{fill(i);selected=i;phase='open';veil.classList.add('show');showScroll()};f.appendChild(b)})}}
function animate(){if(!renderer||!visible||document.hidden){raf=0;return}raf=requestAnimationFrame(animate);const now=performance.now(),t=clock.getElapsedTime();look=mix(look,lookGoal,.045);let camX=look*5,camZ=10.8;
frames.forEach((f,i)=>{const active=selected===i;const p=phase==='opening'?ease((now-phaseStart)/duration):phase==='closing'?1-ease((now-phaseStart)/duration):phase==='open'?1:0;const amt=active?p:0;f.group.position.x=mix(f.origin.x,-1.9,amt);f.group.position.y=mix(f.origin.y+(reduced?0:Math.sin(t*.52+i)*.065),-.2,amt);f.group.position.z=mix(f.origin.z,4.2,amt);f.frame.rotation.y=mix(0,-1.22,amt);f.frame.rotation.z=mix(0,-.07,amt);f.light.intensity=mix(65,100,amt);f.group.visible=!selected||active||amt<.99; if(selected!==-1&&!active)f.light.intensity=7;else if(!active)f.light.intensity=65;});
if(selected!==-1){const p=phase==='opening'?ease((now-phaseStart)/duration):phase==='closing'?1-ease((now-phaseStart)/duration):1;camZ=mix(10.8,9.5,p);camX=mix(camX,-.3,p);if(phase==='opening'&&(now-phaseStart)>=duration){phase='open';showScroll()}if(phase==='closing'&&(now-phaseStart)>=duration){phase='idle';selected=-1;veil.classList.remove('show');document.querySelector('.instruction').textContent='SELECT AN ARTWORK TO UNRAVEL ITS MEANING · DRAG TO LOOK AROUND';}}
camera.position.x=mix(camera.position.x,camX,.055);camera.position.z=mix(camera.position.z,camZ,.055);camera.lookAt(0,-.2,-4);renderer.render(scene,camera)}
init();
